import "../css/dashboard.css";

import logo from "../image/tybwhitelogo.png";

import { useNavigate } from "react-router-dom";

import { DatePicker } from "antd";

import HomeIcon from "@mui/icons-material/Home";

import { useEffect, useState } from "react";

const API_BASE_URL = "http://localhost:5000";

// Special value for Store Customer option
const STORE_CUSTOMER_VALUE = "store";

function Dashboard() {

const navigate = useNavigate();


// ============================================================
// STATE
// ============================================================

const [customer, setCustomer] = useState("");

const [month, setMonth] = useState("");

const [year, setYear] = useState("");

const [resorts, setResorts] = useState([]);

const [productsSold, setProductsSold] = useState([]);

const [loading, setLoading] = useState(false);


// ============================================================
// FETCH RESORT CUSTOMERS
// ============================================================

useEffect(() => {

    fetchResortCustomers();

}, []);


const fetchResortCustomers = async () => {

    try {

        const response = await fetch(
            `${API_BASE_URL}/api/resort-customers`
        );

        if (!response.ok) {

            throw new Error(
                "Failed to fetch resort customers"
            );
        }

        const data = await response.json();

        setResorts(data);

    } catch (error) {

        console.error(
            "Error fetching resort customers:",
            error
        );

    }
};


// ============================================================
// FETCH MONTHLY RESORT SALES
// ============================================================

const fetchResortMonthlyOrders = async (
    customerId,
    selectedMonth,
    selectedYear
) => {

    try {

        setLoading(true);

        const response = await fetch(
            `${API_BASE_URL}/api/resort-customers/${customerId}/monthly-orders?month=${selectedMonth}&year=${selectedYear}`
        );

        if (!response.ok) {

            throw new Error(
                "Failed to fetch resort monthly orders"
            );
        }

        const data = await response.json();

        setProductsSold(data);

    } catch (error) {

        console.error(
            "Error fetching resort monthly orders:",
            error
        );

        setProductsSold([]);

    } finally {

        setLoading(false);
    }
};


// ============================================================
// FETCH MONTHLY SALES FOR ALL STORE CUSTOMERS
// ============================================================

const fetchStoreMonthlySales = async (
    selectedMonth,
    selectedYear
) => {

    try {

        setLoading(true);

        const response = await fetch(
            `${API_BASE_URL}/api/store-customers/monthly-sales?month=${selectedMonth}&year=${selectedYear}`
        );

        if (!response.ok) {

            throw new Error(
                "Failed to fetch store customer monthly sales"
            );
        }

        const data = await response.json();

        setProductsSold(data);

    } catch (error) {

        console.error(
            "Error fetching store customer monthly sales:",
            error
        );

        setProductsSold([]);

    } finally {

        setLoading(false);
    }
};


// ============================================================
// CUSTOMER CHANGE
// ============================================================

const handleCustomerChange = (e) => {

    const selectedCustomer = e.target.value;

    setCustomer(selectedCustomer);

    // Clear old results
    setProductsSold([]);

    // Wait until month is selected
    if (!selectedCustomer || !month || !year) {
        return;
    }


    // ========================================================
    // STORE CUSTOMER
    // ========================================================

    if (selectedCustomer === STORE_CUSTOMER_VALUE) {

        fetchStoreMonthlySales(
            month,
            year
        );

        return;
    }


    // ========================================================
    // RESORT CUSTOMER
    // ========================================================

    fetchResortMonthlyOrders(
        selectedCustomer,
        month,
        year
    );
};


// ============================================================
// MONTH / YEAR CHANGE
// ============================================================

const handleMMYYChange = (date) => {

    if (date) {

        const selectedMonth =
            date.month() + 1;

        const selectedYear =
            date.year();

        setMonth(selectedMonth);

        setYear(selectedYear);

        setProductsSold([]);


        // ====================================================
        // FETCH BASED ON SELECTED CUSTOMER
        // ====================================================

        if (customer) {

            // Store Customer
            if (
                customer === STORE_CUSTOMER_VALUE
            ) {

                fetchStoreMonthlySales(
                    selectedMonth,
                    selectedYear
                );

            }

            // Resort Customer
            else {

                fetchResortMonthlyOrders(
                    customer,
                    selectedMonth,
                    selectedYear
                );
            }
        }

    } else {

        setMonth("");

        setYear("");

        setProductsSold([]);
    }
};


// ============================================================
// SELECTED RESORT
// ============================================================

const selectedResort = resorts.find(
    (r) =>
        String(r.resort_customer_id) ===
        String(customer)
);


// ============================================================
// DISPLAY CUSTOMER NAME
// ============================================================

const displayCustomerName =
    customer === STORE_CUSTOMER_VALUE
        ? "Store Customer"
        : selectedResort?.customer_name;


// ============================================================
// UI
// ============================================================

return (

    <div className="dashboardMain">


        {/* ====================================================
            HEADER
        ==================================================== */}

        <div className="header">

            <div className="headimg">

                <img
                    src={logo}
                    alt="logo"
                />

                <br />

                <span
                    style={{
                        color: "white",
                        paddingLeft: "20px"
                    }}
                >
                    The Yercaud Bean
                </span>

            </div>


            <div>

                <button
                    onClick={() =>
                        navigate("/")
                    }
                >
                    <HomeIcon />
                </button>

            </div>

        </div>


        {/* ====================================================
            TITLE
        ==================================================== */}

        <h2>
            Dashboard
        </h2>


        {/* ====================================================
            FILTERS
        ==================================================== */}

        <div className="dashboardFilter">


            {/* CUSTOMER DROPDOWN */}

            <select
                value={customer}
                onChange={handleCustomerChange}
            >

                <option
                    value=""
                    disabled
                    hidden
                >
                    Select Customer
                </option>


                {/* RESORT CUSTOMERS */}

                {resorts.map((r) => (

                    <option
                        key={r.resort_customer_id}
                        value={r.resort_customer_id}
                    >
                        {r.customer_name}
                    </option>

                ))}


                {/* STORE CUSTOMER */}

                <option
                    value={STORE_CUSTOMER_VALUE}
                >
                    Store Customer
                </option>

            </select>


            {/* MONTH */}

            <DatePicker
                picker="month"
                onChange={handleMMYYChange}
            />

        </div>


        {/* ====================================================
            RESULTS
        ==================================================== */}

        {
            customer &&
            month &&
            year && (

                <div className="dasboardDisplay">


                    {/* CUSTOMER NAME */}

                    <h2>
                        {displayCustomerName}
                    </h2>


                    {/* SELECTED MONTH */}

                    <p>
                        {String(month).padStart(2, "0")}
                        /
                        {year}
                    </p>


                    {/* LOADING */}

                    {loading && (

                        <p>
                            Loading...
                        </p>

                    )}


                    {/* =================================================
                        PRODUCTS
                    ================================================= */}

                    {!loading &&
                        productsSold.length > 0 && (

                            <div className="productSalesDisplay">

                                {productsSold.map(
                                    (
                                        prod,
                                        index
                                    ) => (

                                        <div
                                            className="productItem"
                                            key={
                                                `${prod.item_name || prod.product_name}-${prod.pack_size_grams || ""}-${prod.unit || ""}-${index}`
                                            }
                                        >

                                            {/* PRODUCT NAME */}

                                            <p>

                                                {
                                                    prod.item_name ||
                                                    prod.product_name
                                                }


                                                {/* RESORT PACK SIZE */}

                                                {
                                                    prod.pack_size_grams
                                                        ? ` (${prod.pack_size_grams}g)`
                                                        : ""
                                                }

                                            </p>


                                            {/* QUANTITY */}

                                            <p>

                                                {
                                                    Number(
                                                        prod.total_quantity
                                                    )
                                                }


                                                {/* STORE UNIT */}

                                                {
                                                    prod.unit
                                                        ? ` ${prod.unit}`
                                                        : ""
                                                }

                                            </p>

                                        </div>

                                    )
                                )}

                            </div>

                        )}


                    {/* =================================================
                        NO ORDERS
                    ================================================= */}

                    {!loading &&
                        productsSold.length === 0 && (

                            <p
                                style={{
                                    color: "grey"
                                }}
                            >

                                {
                                    customer ===
                                    STORE_CUSTOMER_VALUE
                                        ? "No store customer orders found for the selected month."
                                        : "No orders found for this resort in the selected month."
                                }

                            </p>

                        )}

                </div>

            )

        }

    </div>
);

}

export default Dashboard;
